// bootrom: 64 x 32-bit boot ROM with two read ports (fetch and data), synthesised as logic
// (docs/SPEC.md §7, MEMORY_MAP "BOOTROM"). Same timing contract as the SRAMs (MICROARCH §3): the
// address is registered at the rising edge, data is valid in the next cycle.
// Content: rtl/soc/bootrom_image.svh, generated by scripts/gen_bootrom.py.
`default_nettype none
module bootrom (
    input  logic        clk,
    input  logic [5:0]  iaddr,
    output logic [31:0] idata,
    input  logic [5:0]  daddr,
    input  logic        den,
    output logic [31:0] ddata
);
`include "bootrom_image.svh"
    logic [5:0] ia_q, da_q;
    always_ff @(posedge clk) begin
        ia_q <= iaddr;
        if (den) da_q <= daddr;
    end
    assign idata = ROM_IMAGE[ia_q];
    assign ddata = ROM_IMAGE[da_q];

    logic unused_words;
    assign unused_words = (ROM_WORDS < 0);
endmodule
`default_nettype wire
